19: @Component({
20:   selector: 'udistrital-crear-grupo-dialog',
21:   templateUrl: './crear-grupo-dialog.component.html',
22:   styleUrl: './crear-grupo-dialog.component.scss',
23: })
24: export class CrearGrupoDialogComponent implements OnInit {
25:   espaciosAcademicos: any;
26:   inputsFormStepDos!: any;
27:   formPaso1!: FormGroup;
28:   formPaso2!: FormGroup;
29:   gruposDeEspacioAcademico: any[] = [];
30:   grupoEstudio: any;
31:   idGruposYaSeleccionados: any[] = [];
32: 
33:   constructor(
34:     @Inject(MAT_DIALOG_DATA) public infoGrupoEstudio: any,
35:     private formBuilder: FormBuilder,
36:     public dialogRef: MatDialogRef<CrearGrupoDialogComponent>,
37:     public dialog: MatDialog,
38:     private espacioAcademicoService: EspacioAcademicoService,
39:     private horarioService: HorarioService,
40:     private horarioMid: HorarioMidService,
41:     private parametros: Parametros,
42:     private popUpManager: PopUpManager,
43:     private translate: TranslateService
44:   ) {}
45: 
46:   ngOnInit(): void {
47:     this.iniciarFormularios();
48:     this.obtenerMateriasSegunPlanYSemestre();
49:   }
50: 
51:   obtenerMateriasSegunPlanYSemestre(): void {
52:     this.parametros
53:       .obtenerMateriasSegunPlanYSemestre(
54:         this.infoGrupoEstudio.planEstudio,
55:         this.infoGrupoEstudio.semestre.NumeroOrden
56:       )
57:       .subscribe((res) => {
58:         this.espaciosAcademicos = res;
59:       });
60:   }
61: 
62:   iniciarFormularios(): void {
63:     this.formPaso1 = this.formBuilder.group({
64:       espaciosGrupos: this.formBuilder.array([this.crearGrupoForm()]),
65:     });
66: 
67:     this.formPaso2 = this.formBuilder.group({
68:       codigoProyecto: ['', Validators.required],
69:       indicador: ['', Validators.required],
70:       codigoResultado: [{ value: '', disabled: true }, Validators.required],
71:       capacidad: ['', Validators.required],
72:     });
73: 
74:     this.formPaso2.valueChanges.subscribe(() =>
75:       this.actualizarCodigoResultado()
76:     );
77:     this.inputsFormStepDos = inputsFormStepDos;
78:   }
79: 
80:   cargarGruposDeEspacioAcademico(espacioAcademico: any, index: number): void {
81:     const periodoId = this.infoGrupoEstudio.periodo.Id;
82:     this.espacioAcademicoService
83:       .get(
84:         `espacio-academico?query=activo:true,periodo_id:${periodoId},espacio_academico_padre:${espacioAcademico._id}`
85:       )
86:       .subscribe((res: any) => {
87:         if (res.Success && res.Data.length > 0) {
88:           this.gruposDeEspacioAcademico[index] = res.Data;
89:         } else {
90:           this.popUpManager.showAlert(
91:             '',
92:             this.translate.instant(
93:               'gestion_horarios.espacio_academico_sin_grupos'
94:             )
95:           );
96:         }
97:       });
98:   }
99: 
100:   agregarEspacioGrupo(): void {
101:     if (this.validarSelectsLlenos()) {
102:       this.listaEspaciosGrupos.push(this.crearGrupoForm());
103:     }
104:   }
105: 
106:   eliminarEspacioGrupo(grupo: any, index: any): void {
107:     this.listaEspaciosGrupos.removeAt(index);
108: 
109:     const grupoId = grupo.value.grupo._id;
110:     this.idGruposYaSeleccionados = this.idGruposYaSeleccionados.filter(
111:       (id: string) => id !== grupoId
112:     );
113:   }
114: 
115:   get listaEspaciosGrupos(): FormArray {
116:     return this.formPaso1.get('espaciosGrupos') as FormArray;
117:   }
118: 
119:   crearGrupoForm(): FormGroup {
120:     return this.formBuilder.group({
121:       espacioAcademico: ['', Validators.required],
122:       grupo: ['', Validators.required],
123:     });
124:   }
125: 
126:   preguntarCreadoGrupoEstudio(): void {
127:     this.construirObjetoGrupoEstudio().subscribe((grupoEstudio: any) => {
128:       this.popUpManager
129:         .showConfirmAlert(
130:           this.translate.instant(
131:             'gestion_horarios.esta_seguro_crear_grupo_personas'
132:           )
133:         )
134:         .then((confirmado) => {
135:           if (!confirmado.value) {
136:             return;
137:           }
138: 
139:           this.crearGrupoEstudio(grupoEstudio);
140:         });
141:     });
142:   }
143: 
144:   crearGrupoEstudio(grupoEstudio: any) {
145:     this.horarioMid
146:       .post('grupo-estudio', grupoEstudio)
147:       .subscribe((res: any) => {
148:         if (res.Success) {
149:           this.popUpManager.showSuccessAlert(
150:             this.translate.instant('gestion_horarios.grupo_personas_creado')
151:           );
152:           this.dialogRef.close(true);
153:         } else {
154:           this.popUpManager.showErrorAlert(
155:             this.translate.instant(
156:               'gestion_horarios.error_crear_grupo_personas'
157:             )
158:           );
159:         }
160:       });
161:   }
162: 
163:   actualizarCodigoResultado(): void {
164:     const codigoProyecto = this.formPaso2.get('codigoProyecto')?.value || '';
165:     const indicador = this.formPaso2.get('indicador')?.value || '';
166:     this.formPaso2
167:       .get('codigoResultado')
168:       ?.setValue(`${codigoProyecto} ${indicador}`, { emitEvent: false });
169:   }
170: 
171:   validarSelectsLlenos(): boolean {
172:     return this.listaEspaciosGrupos.controls.every((group) => group.valid);
173:   }
174: 
175:   verificarSiGrupoYaFueAgregado(grupo: any, index: any) {
176:     const yaEsta = this.idGruposYaSeleccionados.includes(grupo.value._id);
177:     if (yaEsta) {
178:       const grupoForm = this.listaEspaciosGrupos.at(index) as FormGroup;
179:       grupoForm.get('grupo')?.reset();
180:       return this.popUpManager.showAlert(
181:         '',
182:         this.translate.instant('gestion_horarios.grupo_ya_seleccionado')
183:       );
184:     }
185: 
186:     if (grupo.value.grupo_estudio_id && grupo.value.grupo_estudio_id != '0') {
187:       const grupoForm = this.listaEspaciosGrupos.at(index) as FormGroup;
188:       grupoForm.get('grupo')?.reset();
189:       return this.popUpManager.showAlert(
190:         '',
191:         this.translate.instant(
192:           'gestion_horarios.espacio_ya_esta_en_otro_grupo_estudio'
193:         )
194:       );
195:     }
196: 
197:     this.idGruposYaSeleccionados.push(grupo.value._id);
198:   }
199: 
