200:   construirObjetoGrupoEstudio(): any {
201:     const { horario, semestre } = this.infoGrupoEstudio;
202:     const idEspaciosAcademicos = this.listaEspaciosGrupos.value.map(
203:       (espacioGrupo: any) => espacioGrupo.grupo._id
204:     );
205:     return this.horarioService
206:       .get('estado-creacion-semestre?query=Nombre:Aprobado&fields=_id')
207:       .pipe(
208:         map((res: any) => ({
209:           CodigoProyecto: this.formPaso2.get('codigoProyecto')?.value,
210:           IndicadorGrupo: this.formPaso2.get('indicador')?.value,
211:           CuposGrupos: this.formPaso2.get('capacidad')?.value,
212:           EspaciosAcademicos: idEspaciosAcademicos,
213:           SemestreId: semestre.Id,
214:           HorarioId: horario._id,
215:           EstadoCreacionSemestreId: res.Data[0]._id,
216:           Observacion: 'Vacio',
217:           Activo: true,
218:         }))
219:       );
220:   }
221: 
222:   abrirDialogoCrearEspacioGrupo(espacioAcademico: any, index: any) {
223:     const dialogRef = this.dialog.open(CrearEspacioGrupoDialogComponent, {
224:       width: '50%',
225:       height: 'auto',
226:       data: {
227:         espacioAcademico: espacioAcademico,
228:         periodo: this.infoGrupoEstudio.periodo,
229:       },
230:     });
231: 
232:     dialogRef.afterClosed().subscribe((grupoEspacio) => {
233:       if (grupoEspacio && grupoEspacio.creado) {
234:         this.cargarGruposDeEspacioAcademico(
235:           { _id: grupoEspacio.info.espacio_academico_padre },
236:           index
237:         );
238:       }
239:     });
240:   }
241: }

