684:   private async cargarDatosAuditado(): Promise<void> {
685:     try {
686:       const personaId = await this.userService.getPersonaId();
687:       if (!this.usuarioId) this.usuarioId = personaId;
688: 
689:       const cargoId = this.role === environment.ROL.JEFE_DEPENDENCIA
690:         ? environment.CARGO.JEFE_DEPENDENCIA_ID
691:         : environment.CARGO.ASISTENTE_DEPENDENCIA_ID;
692: 
693:       const vinculacionRes: any = await firstValueFrom(
694:         this.tercerosCrudService.get(`vinculacion?query=TerceroPrincipalId:${personaId},Activo:true,CargoId:${cargoId}&fields=DependenciaId`)
695:       );
696:       this.dependenciaIds = (vinculacionRes ?? [])
697:         .map((v: any) => v.DependenciaId)
698:         .filter((id: any) => id != null);
699: 
700:       const informeRes: any = await firstValueFrom(
701:         this.planAuditoriaService.get(`informe?query=auditoria_id:${this.auditoriaId}`)
702:       );
703:       this.informeData = informeRes?.Data?.[0] ?? null;
704:       this.informeId = this.informeData?._id ?? null;
705: 
706:       const auditoriaRes: any = await firstValueFrom(
707:         this.planAuditoriaMid.get(`auditoria/${this.auditoriaId}`)
708:       );
709:       this.datosDependencias = auditoriaRes?.Data?.datos_dependencias ?? [];
710: 
711:       // Solo las dependencias del usuario que pertenecen a esta auditoría
712:       const depAuditoriaIds: number[] = this.datosDependencias
713:         .map((d: any) => d.dependencia_id)
714:         .filter((id: any) => id != null);
715:       this.dependenciaIds = this.dependenciaIds.filter(id => depAuditoriaIds.includes(id));
716: 
717:       const decididas: number[] = this.informeData?.dependencias_decididas ?? [];
718:       this.dependenciaYaDecidio = this.dependenciaIds.some(id => decididas.includes(id));
719: 
720:       if (!this.dependenciaYaDecidio && this.informeId) {
721:         const hallazgosRes: any = await firstValueFrom(
722:           this.planAuditoriaService.get(`hallazgo?query=informe_id:${this.informeId}&limit=0`)
723:         );
724:         const hallazgos = hallazgosRes?.Data ?? [];
725:         if (hallazgos.length) {
726:           const ids = hallazgos.map((h: any) => h._id).join('|');
727:           const obsRes: any = await firstValueFrom(
728:             this.planAuditoriaService.get(`observacion?query=hallazgo_id__in:${ids},activo:true&limit=0`)
729:           );
730:           const todasObs: any[] = obsRes?.Data ?? [];
731:           this.dependenciaTieneObservaciones = todasObs.some(obs => {
732:             const depIds: number[] = Array.isArray(obs.dependencia_id) ? obs.dependencia_id : [obs.dependencia_id];
733:             return depIds.some(id => this.dependenciaIds.includes(id));
734:           });
735:         } else {
736:           this.dependenciaTieneObservaciones = false;
737:         }
738:       }
739:     } catch (error) {
740:       console.error('Error al cargar datos del auditado:', error);
741:     }
742:   }
