83:   private flattenObject(obj: any, prefix: string = ''): any {
84:     let items: any = {};
85:     for (let key in obj) {
86:       if (obj.hasOwnProperty(key)) {
87:         const newKey = prefix ? `${prefix}.${key}` : key;
88:         if (typeof obj[key] === 'object' && obj[key] !== null) {
89:           Object.assign(items, this.flattenObject(obj[key], newKey));
90:         } else {
91:           items[newKey] = obj[key];
92:         }
93:       }
94:     }
95:     return items;
96:   }
